const store = getWorkflowStaticData('global');
store.sessions ??= {};
store.processed ??= {};
store.deadletter ??= [];
store.appointments ??= {};

const now = Date.now();
for (const [k, v] of Object.entries(store.processed)) {
  if (typeof v === 'number' && now - v > 7 * 24 * 60 * 60 * 1000) delete store.processed[k];
}

const message = $json.message || {};
const chatId = String(message?.chat?.id || '');
const messageId = String(message?.message_id || '');
const text = typeof message?.text === 'string' ? message.text.trim() : '';

if (!chatId || !messageId) {
  return [{ json: { route: 'DROP_DUPLICATE', action: 'NOOP' } }];
}

const dedupeKey = `${chatId}:${messageId}`;
if (store.processed[dedupeKey]) {
  return [{ json: { route: 'DROP_DUPLICATE', action: 'NOOP', chatId, messageId } }];
}
store.processed[dedupeKey] = now;

const existing = store.sessions[chatId] || {
  state: 'NEED_NAME',
  data: { language: 'en' },
  updatedAt: new Date().toISOString()
};

if (!text) {
  return [{
    json: {
      route: 'ASK_NON_TEXT',
      action: 'ASK_USER',
      chatId,
      messageId,
      session: existing,
      replyText: 'Please send a text message so I can continue your booking.'
    }
  }];
}

if (/[\u0900-\u097F]/.test(text)) {
  existing.data.language = 'hi';
}

return [{
  json: {
    route: 'ADVANCE',
    action: 'ADVANCE',
    chatId,
    messageId,
    text,
    session: existing
  }
}];

function pad(n){ return String(n).padStart(2,'0'); }
function istNow(){ return new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Kolkata' })); }
function ymdFromDate(d){ return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; }
function compareYmd(a,b){ if(a===b) return 0; return a>b?1:-1; }
function toAmPm(h,m){ const hh = h % 12 === 0 ? 12 : h % 12; const ampm = h >= 12 ? 'PM' : 'AM'; return `${pad(hh)}:${pad(m)} ${ampm}`; }
function weekday(ymd){ const [y,m,d] = ymd.split('-').map(Number); return new Date(Date.UTC(y,m-1,d)).getUTCDay(); }
function detectPeriod(text){ const t = text.toLowerCase(); if(/morning|subah|am/.test(t)) return 'MORNING'; if(/evening|afternoon|shaam|pm|raat/.test(t)) return 'EVENING'; return null; }
function normalizeMobile(text){ const digits = text.replace(/\D/g,''); if(digits.length===10) return digits; if(digits.length===12 && digits.startsWith('91')) return digits.slice(2); return null; }
function normalizeName(text){ const cleaned = text.replace(/[^a-zA-Z\s]/g,' ').trim().replace(/\s+/g,' '); if(cleaned.length < 2) return null; return cleaned.split(' ').map(w=>w.charAt(0).toUpperCase()+w.slice(1).toLowerCase()).join(' '); }
function parseDateInput(text){
 const t = text.trim().toLowerCase();
 const now = istNow();
 if(/^tomorrow$|^kal$/.test(t)){ const d = new Date(now); d.setDate(d.getDate()+1); return ymdFromDate(d); }
 if(/^today$|^aaj$/.test(t)){ return ymdFromDate(now); }
 let m = t.match(/^(\d{1,2})[-\/](\d{1,2})(?:[-\/](\d{4}))?$/);
 if(m){ const day = Number(m[1]); const mon = Number(m[2]); const yr = m[3]?Number(m[3]):now.getFullYear(); if(day>=1&&day<=31&&mon>=1&&mon<=12) return `${yr}-${pad(mon)}-${pad(day)}`; }
 m = t.match(/^(\d{1,2})\s*(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)(?:\s*(\d{4}))?$/i);
 if(m){ const months = {jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,sept:9,oct:10,nov:11,dec:12}; const day=Number(m[1]); const mon=months[m[2].toLowerCase()]; const yr=m[3]?Number(m[3]):now.getFullYear(); if(day>=1&&day<=31) return `${yr}-${pad(mon)}-${pad(day)}`; }
 return null;
}
function generateSlots(ymd, period){
 const day = weekday(ymd);
 const windows = {0:[['18:30','21:30']],1:[['18:30','21:30']],2:[['18:30','21:30']],3:[['18:30','21:30']],4:[['18:30','21:30']],5:[['18:30','21:30']],6:[['10:30','13:00'],['18:30','21:30']]};
 const defs = windows[day] || [];
 const slots = [];
 for(const [start,end] of defs){
  const [sh,sm] = start.split(':').map(Number);
  const [eh,em] = end.split(':').map(Number);
  let curMin = sh*60 + sm;
  const endMin = eh*60 + em;
  while(curMin + 10 <= endMin){
   const h = Math.floor(curMin/60); const m = curMin % 60;
   const isMorning = h < 12;
   if((period==='MORNING' && isMorning) || (period==='EVENING' && !isMorning)){
    const next = curMin + 10;
    const ehh = Math.floor(next/60); const emm = next%60;
    const startIso = `${ymd}T${pad(h)}:${pad(m)}:00+05:30`;
    const endIso = `${ymd}T${pad(ehh)}:${pad(emm)}:00+05:30`;
    slots.push({ display: toAmPm(h,m), startIso, endIso });
   }
   curMin += 10;
  }
 }
 return slots;
}
function parseSlot(text){ const m = text.toUpperCase().match(/\b(1[0-2]|0?[1-9]):([0-5][0-9])\s*(AM|PM)\b/); if(!m) return null; const h=String(m[1]).padStart(2,'0'); return `${h}:${m[2]} ${m[3]}`; }
function isYes(text){ return /^(yes|confirm|ok|haan|ha|kar do|confirm karo)$/i.test(text.trim()); }
function isNo(text){ return /^(no|nah|nahi|cancel)$/i.test(text.trim()); }

const input = $json;
const text = String(input.text || '').trim();
const chatId = String(input.chatId || '');
let session = input.session || { state: 'NEED_NAME', data: { language: 'en' } };
session.data ??= {};
const lang = session.data.language === 'hi' ? 'hi' : 'en';
const ask = (en, hi) => (lang === 'hi' ? hi : en);

if (session.state === 'BOOKED') {
  const t = text.toLowerCase();
  if (/(cancel|cancellation|band)/.test(t) && session.data.calendarEventId) {
    session.data.rescheduleFlow = false;
    return [{ json: { action: 'DELETE_EVENT', chatId, session, toolPayload: { eventId: session.data.calendarEventId } } }];
  }
  if (/(reschedule|change|shift|move)/.test(t) && session.data.calendarEventId) {
    session.state = 'RESCHEDULE_PENDING';
    session.data.rescheduleFlow = true;
    return [{ json: { action: 'DELETE_EVENT', chatId, session, toolPayload: { eventId: session.data.calendarEventId } } }];
  }
  const done = ask(
    `Your appointment is already confirmed for ${session.data.bookingDate || ''} ${session.data.bookingTime || ''}. Reply 'cancel' or 'reschedule' to modify.`,
    `Aapka appointment ${session.data.bookingDate || ''} ${session.data.bookingTime || ''} ke liye confirm hai. Badalne ke liye 'cancel' ya 'reschedule' likhein.`
  );
  return [{ json: { action: 'ASK_USER', chatId, session, replyText: done } }];
}

switch (session.state) {
  case 'NEED_NAME': {
    const name = normalizeName(text);
    if (!name) return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('Could I please get your full name?', 'Kripya apna poora naam batayein.') } }];
    session.data.patientName = name;
    session.state = 'NEED_MOBILE';
    return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask(`Thank you, ${name}. Could I please have your 10-digit mobile number?`, `Dhanyavaad ${name}. Kripya apna 10-digit mobile number share karein.`) } }];
  }
  case 'NEED_MOBILE': {
    const mobile = normalizeMobile(text);
    if (!mobile) return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('Please share a valid 10-digit mobile number.', 'Kripya valid 10-digit mobile number bhejein.') } }];
    session.data.mobile = mobile;
    session.state = 'NEED_DATE';
    return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('What date would you like to visit Dr. Sumit? (DD-MM-YYYY)', 'Aap kis date ko appointment chahte hain? (DD-MM-YYYY)') } }];
  }
  case 'NEED_DATE': {
    const ymd = parseDateInput(text);
    if (!ymd) return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('Please share a valid date in DD-MM-YYYY format.', 'Kripya valid date DD-MM-YYYY format mein bhejein.') } }];
    const today = ymdFromDate(istNow());
    if (compareYmd(ymd, today) <= 0) return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('I apologize, but we do not accept same-day or past bookings. Could I book you for tomorrow or a later date?', 'Same-day ya past date booking allowed nahi hai. Kripya kal ya uske baad ki date batayein.') } }];
    session.data.requestedDate = ymd;
    session.state = 'NEED_PERIOD';
    return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('Would you prefer a morning or an evening appointment?', 'Kya aap morning slot chahenge ya evening slot?') } }];
  }
  case 'NEED_PERIOD': {
    const period = detectPeriod(text);
    if (!period) return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('Please choose morning or evening.', 'Kripya morning ya evening choose karein.') } }];
    const slots = generateSlots(session.data.requestedDate, period);
    if (!slots.length) return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('No slots available for this preference. Please choose the other half of the day.', 'Is preference mein slot available nahi hai. Kripya doosra time preference batayein.') } }];
    session.data.period = period;
    session.data.candidateSlots = slots;
    return [{ json: { action: 'CHECK_AVAILABILITY', chatId, session, toolPayload: { timeMin: slots[0].startIso, timeMax: slots[slots.length - 1].endIso, candidateSlots: slots } } }];
  }
  case 'NEED_SLOT_SELECTION': {
    const normalized = parseSlot(text);
    const free = session.data.freeSlots || [];
    if (!normalized) return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('Please send a valid slot like 06:40 PM.', 'Kripya valid slot bhejein, jaise 06:40 PM.') } }];
    const selected = free.find(s => String(s.display).toUpperCase() === normalized);
    if (!selected) return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask(`Please choose from: ${free.map(s=>s.display).join(', ')}`, `Kripya in mein se choose karein: ${free.map(s=>s.display).join(', ')}`) } }];
    session.data.selectedSlot = selected;
    session.state = 'NEED_CONFIRMATION';
    const summary = `Name: ${session.data.patientName}\nMobile: ${session.data.mobile}\nDate: ${session.data.requestedDate}\nTime: ${selected.display}`;
    return [{ json: { action: 'ASK_USER', chatId, session, replyText: `${summary}\n${ask('Shall I confirm this for you?', 'Kya main isse confirm kar doon?')}` } }];
  }
  case 'NEED_CONFIRMATION': {
    if (isNo(text)) {
      session.state = 'NEED_DATE';
      session.data.requestedDate = undefined;
      session.data.period = undefined;
      session.data.candidateSlots = undefined;
      session.data.freeSlots = undefined;
      session.data.selectedSlot = undefined;
      return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('No problem. What new date would you like?', 'Theek hai. Aap kaunsi nayi date chahte hain?') } }];
    }
    if (!isYes(text) || !session.data.selectedSlot) {
      return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask("Please type 'yes' to confirm or 'no' to change.", "Confirm ke liye 'yes' aur badalne ke liye 'no' likhiye.") } }];
    }
    const sel = session.data.selectedSlot;
    const idempotencyKey = `${chatId}:${sel.startIso}`;
    return [{ json: { action: 'CREATE_EVENT', chatId, session, toolPayload: { startIso: sel.startIso, endIso: sel.endIso, summary: `Booking: ${session.data.patientName} - ${session.data.mobile}`, idempotencyKey } } }];
  }
  case 'RESCHEDULE_PENDING': {
    session.state = 'NEED_DATE';
    return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('What new date would you like? (DD-MM-YYYY)', 'Aapko kaunsi nayi date chahiye? (DD-MM-YYYY)') } }];
  }
  case 'CANCELLED': {
    session.state = 'NEED_DATE';
    return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('Would you like to book a new appointment date?', 'Kya aap nayi appointment date book karna chahenge?') } }];
  }
  default: {
    session.state = 'NEED_NAME';
    return [{ json: { action: 'ASK_USER', chatId, session, replyText: ask('Could I please get your full name?', 'Kripya apna poora naam batayein.') } }];
  }
}

const ctx = $('State Machine Engine').first().json;
const events = $input.all().map(i => i.json);
const busy = new Set();
for (const e of events) {
  const dt = e?.start?.dateTime || e?.start;
  if (typeof dt === 'string') busy.add(new Date(dt).toISOString());
}
const candidates = Array.isArray(ctx?.toolPayload?.candidateSlots) ? ctx.toolPayload.candidateSlots : [];
const free = candidates.filter(s => !busy.has(new Date(s.startIso).toISOString())).slice(0,3);
const session = ctx.session || { state: 'NEED_PERIOD', data: {} };
const lang = session?.data?.language === 'hi' ? 'hi' : 'en';
const ask = (en, hi) => (lang === 'hi' ? hi : en);
let replyText = '';
if (!free.length) {
  session.state = 'NEED_PERIOD';
  replyText = ask('No slots are available for this preference. Please choose the other half of the day.', 'Is preference mein slot available nahi hai. Kripya doosra time preference batayein.');
} else {
  session.state = 'NEED_SLOT_SELECTION';
  session.data.freeSlots = free;
  replyText = ask(`Please choose from the following available slots: ${free.map(s => s.display).join(', ')}`, `Kripya in available slots mein se choose karein: ${free.map(s => s.display).join(', ')}`);
}
return [{ json: { action: 'ASK_USER', chatId: ctx.chatId, session, replyText } }];

const ctx = $('State Machine Engine').first().json;
const session = ctx.session || { state: 'BOOKED', data: {} };
const eventId = $('Create Calendar Event').first().json.id;
session.state = 'BOOKED';
session.data.calendarEventId = eventId;
session.data.bookingDate = session.data.requestedDate;
session.data.bookingTime = session.data.selectedSlot?.display || '';
const chatId = ctx.chatId;
const replyText = `✅ Your appointment is confirmed!\n\n👤 Patient Name: ${session.data.patientName}\n📞 Mobile Number: ${session.data.mobile}\n📅 Booking Date: ${session.data.bookingDate}\n🕐 Booking Time: ${session.data.bookingTime}\n\n📍 Dr. Sumit Homeopathy Clinic\nShop No. UFF-16A, Ecomart, Supertech Ecovillage 1, Greater Noida`;
const store = getWorkflowStaticData('global');
store.appointments ??= {};
store.appointments[ctx.toolPayload.idempotencyKey] = {
  chatId,
  patientName: session.data.patientName,
  mobile: session.data.mobile,
  startIso: session.data.selectedSlot?.startIso,
  endIso: session.data.selectedSlot?.endIso,
  eventId,
  reminderSent: false
};
return [{ json: { action: 'ASK_USER', chatId, session, replyText } }];

const ctx = $('State Machine Engine').first().json;
const session = ctx.session || { state: 'NEED_CONFIRMATION', data: {} };
const chatId = ctx.chatId;
const store = getWorkflowStaticData('global');
store.deadletter ??= [];
store.deadletter.push({
  id: `${Date.now()}-${Math.random().toString(16).slice(2)}`,
  type: 'CREATE_EVENT',
  chatId,
  payload: ctx.toolPayload,
  error: $('Create Calendar Event').first().json.error?.message || 'Calendar create failed',
  createdAt: new Date().toISOString(),
  status: 'queued'
});
const replyText = 'We are facing a temporary system delay. Your request is queued and we will confirm shortly.';
return [{ json: { action: 'ASK_USER', chatId, session, replyText } }];

const ctx = $('State Machine Engine').first().json;
const session = ctx.session || { state: 'CANCELLED', data: {} };
const chatId = ctx.chatId;
let replyText = '';
if (session.data.rescheduleFlow) {
  session.state = 'NEED_DATE';
  session.data.calendarEventId = undefined;
  session.data.bookingDate = undefined;
  session.data.bookingTime = undefined;
  session.data.selectedSlot = undefined;
  session.data.freeSlots = undefined;
  session.data.candidateSlots = undefined;
  replyText = session.data.language === 'hi' ? 'Appointment reschedule request liya gaya. Kripya nayi date batayein. (DD-MM-YYYY)' : 'Your reschedule request is done. Please share the new date. (DD-MM-YYYY)';
} else {
  session.state = 'CANCELLED';
  session.data.calendarEventId = undefined;
  replyText = session.data.language === 'hi' ? 'Aapka appointment cancel kar diya gaya hai.' : 'Your appointment has been cancelled.';
}
return [{ json: { action: 'ASK_USER', chatId, session, replyText } }];

const ctx = $('State Machine Engine').first().json;
const store = getWorkflowStaticData('global');
store.deadletter ??= [];
store.deadletter.push({
  id: `${Date.now()}-${Math.random().toString(16).slice(2)}`,
  type: 'DELETE_EVENT',
  chatId: ctx.chatId,
  payload: ctx.toolPayload,
  error: $('Delete Calendar Event').first().json.error?.message || 'Calendar delete failed',
  createdAt: new Date().toISOString(),
  status: 'queued'
});
return [{ json: { action: 'ASK_USER', chatId: ctx.chatId, session: ctx.session, replyText: 'We are facing a temporary system delay. Your request is queued and we will confirm shortly.' } }];

const store = getWorkflowStaticData('global');
store.sessions ??= {};
const chatId = String($json.chatId || '');
if (chatId && $json.session) {
  $json.session.updatedAt = new Date().toISOString();
  store.sessions[chatId] = $json.session;
}
return items;
